#!/usr/bin/env node

import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { compileHumanEvalSuitesFromMarkdown } from '@agent-assistant/telemetry/evals';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const SUITES_DIR = path.join(ROOT, 'evals', 'suites');
const GENERATED_HEADER = [
  '# Generated by scripts/evals/compile-ricky-evals.mjs from cases.md.',
  '# Do not edit this file directly; edit cases.md in this suite instead.',
].join('\n');

const args = parseArgs(process.argv.slice(2));
const result = compileHumanEvalSuitesFromMarkdown({
  suitesDir: SUITES_DIR,
  suite: args.suite,
  generatedHeader: GENERATED_HEADER,
});

for (const suite of result.suites) {
  console.log(`${path.relative(ROOT, suite.outputPath)}: wrote ${suite.cases.length} cases`);
}
console.log(`Compiled ${result.total} Ricky eval cases.`);

function parseArgs(argv) {
  const parsed = {};
  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    if (arg === '--suite') parsed.suite = readOptionValue(argv, ++index, '--suite');
    else if (arg === '--help' || arg === '-h') {
      printHelp();
      process.exit(0);
    } else {
      throw new Error(`Unknown argument: ${arg}`);
    }
  }
  return parsed;
}

function readOptionValue(argv, index, option) {
  const value = argv[index];
  if (value === undefined || value.startsWith('--')) {
    throw new Error(`${option} requires a value`);
  }
  return value;
}

function printHelp() {
  console.log(`Usage: node scripts/evals/compile-ricky-evals.mjs [--suite NAME]

Reads evals/suites/*/cases.md and writes generated cases.jsonl files.
`);
}
